void Solver::bump_var(int var, double coeff) {
    // Compute increment based on current var_inc
    double inc = var_inc * coeff;
    activity[var] += inc;

    // Lazy global rescaling: only when the global increment factor grows too large.
    // This avoids frequent per-variable overflow checks and reduces the cost of the scaling loop.
    if (var_inc > 1e100) {
        const double scale = 1e-100;          // bring values back into a safe range
        for (int i = 1; i <= vars; ++i) {
            activity[i] *= scale;
        }
        var_inc *= scale;
    }

    // Keep the VSIDS heap up‑to‑date
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}
